sysauto_script.script:
/**
 * Monitor Grievance SLA Breaches
 *
 * Runs every 15 minutes. Finds active grievance tickets whose Target
 * Resolution deadline has passed and that have not already been escalated,
 * marks them Overdue, stamps a work note, and fires
 * x_1850267_public_0.sla.breached so the escalation notification goes out to
 * the assigned agent and every grievance manager.
 *
 * Uses new GlideDateTime() (scoped-safe) rather than gs.nowDateTime().
 */
;(function () {
    var GRIEVANCE_TABLE = 'x_1850267_public_0_grievance'
    var MANAGER_ROLE = 'x_1850267_public_0.grievance_manager'
    var SLA_BREACHED_EVENT = 'x_1850267_public_0.sla.breached'
    var ESCALATION_OVERDUE = 3

    /**
     * Comma-separated sys_ids of active users holding the grievance manager
     * role. Passed as event parm 1 so the notification can resolve them as
     * recipients.
     */
    function getManagerSysIds() {
        var ids = []
        var roleGr = new GlideRecord('sys_user_has_role')
        roleGr.addQuery('role.name', MANAGER_ROLE)
        roleGr.addQuery('user.active', true)
        roleGr.query()

        while (roleGr.next()) {
            var userId = roleGr.getValue('user')
            if (userId && ids.indexOf(userId) === -1) {
                ids.push(userId)
            }
        }

        return ids.join(',')
    }

    try {
        var now = new GlideDateTime()
        var managerSysIds = getManagerSysIds()

        if (!managerSysIds) {
            gs.warn(
                '[Grievance SLA Monitor] No active users hold ' +
                    MANAGER_ROLE +
                    '. Breach events will still fire, but only the assigned agent will be emailed.',
            )
        }

        var gr = new GlideRecord(GRIEVANCE_TABLE)
        gr.addQuery('active', true)
        gr.addNotNullQuery('target_resolution')
        gr.addQuery('target_resolution', '<', now.getValue())
        gr.addQuery('escalation', '<', ESCALATION_OVERDUE)
        gr.query()

        var escalated = 0

        while (gr.next()) {
            var deadline = gr.getDisplayValue('target_resolution')
            var ticketNumber = gr.getValue('number')

            gr.setValue('escalation', ESCALATION_OVERDUE)
            gr.work_notes =
                'SLA BREACH: This grievance breached its Target Resolution deadline of ' +
                deadline +
                ' and has been escalated to Overdue. Grievance managers have been notified.'

            if (gr.update()) {
                gs.eventQueue(SLA_BREACHED_EVENT, gr, managerSysIds, deadline)
                escalated++
            } else {
                gs.error('[Grievance SLA Monitor] Failed to update breached grievance ' + ticketNumber)
            }
        }

        gs.info(
            '[Grievance SLA Monitor] Run at ' +
                now.getDisplayValue() +
                ' escalated ' +
                escalated +
                ' breached grievance ticket(s).',
        )
    } catch (e) {
        gs.error('[Grievance SLA Monitor] Aborted with error: ' + e.message)
    }
})()
